init(){return {t:0,cursor:0,mode:'up',next:'down',turnSign:1,ox:0,oy:0,stepRemaining:0,coast:0,moving:false,events:[]};},
step(s,acts,dt){
 if(s.blend){s.blend.left-=dt;if(s.blend.left<=0)s.blend=null;}
 const has=id=>acts.some(a=>a.id===id);
 if(has('turn'))turn(s);
 if(has('step'))s.stepRemaining=Math.max(s.stepRemaining,.62);
 let desired=has('up')?'up':has('down')?'down':null;
 if(desired&&s.mode!=='turn'&&desired!==s.mode)turn(s);
 if(s.mode==='turn'){
  s.cursor+=dt*s.turnSign;
  if(s.cursor>=7.6-1e-9||s.cursor<=5.1+1e-9){
   s.cursor=clamp(s.cursor,5.1,7.6);s.mode=s.next;
   if(s.mode==='up'){
    // Pick the uphill gait position nearest the current supporting feet.
    let at=root(s.cursor)[0]+s.ox,best=0,err=1e9;
    for(let p=0;p<3.5;p+=.04){let e=Math.abs(root(p)[0]-at);if(e<err){err=e;best=p;}}
    shiftClip(s,best);
   }
  }
 }else{
  let active=desired===s.mode||s.stepRemaining>0;
  if(s.moving&&!active)s.coast=.12;
  s.moving=active;
  let speed=active?1:s.coast>0?s.coast/.12:0;
  s.coast=Math.max(0,s.coast-dt);s.stepRemaining=Math.max(0,s.stepRemaining-dt);
  if(speed>0){
   let before=s.cursor;s.cursor+=dt*speed;
   if(s.mode==='up')s.cursor=Math.min(5.1,s.cursor);
   else s.cursor=Math.min(9.48,s.cursor);
   if(Math.abs(s.ox)>1||Math.abs(s.oy)>1){let foot=root(s.cursor);if(foot[1]+s.oy>990)s.oy=990-foot[1];if(foot[0]+s.ox<620)s.ox=620-foot[0];}
   if(Math.floor(before/.6)!==Math.floor(s.cursor/.6))s.events.push({type:'foot_contact'});
  }
 }
},
